ive_review.md#source\npub fn parse_archive_review_verdict(review_path: &Path) -> Result<ArchiveReviewVerdict> {\n    if !review_path.exists() {\n        return Ok(ArchiveReviewVerdict::Unknown);\n    }\n\n    let content = std::fs::read_to_string(review_path)?;\n    let content_lower = content.to_lowercase();\n\n    // Primary: Look for checked boxes (generated by MCP tool)\n    if content_lower.contains(\"[x] approved\") {\n        return Ok(ArchiveReviewVerdict::Approved);\n    }\n    if content_lower.contains(\"[x] reviewed\") || content_lower.contains(\"[x] needs fix\") {\n        return Ok(ArchiveReviewVerdict::Reviewed);\n    }\n    if content_lower.contains(\"[x] rejected\") {\n        return Ok(ArchiveReviewVerdict::Rejected);\n    }\n\n    // Fallback: Look for \"verdict: X\" or \"**verdict**: X\" patterns (LLM direct output)\n    for line in content_lower.lines() {\n        let line = line.trim();\n        // Match patterns like \"verdict: approved\", \"**verdict**: approved\", \"verdict:** approved\"\n        if line.contains(\"verdict\") {\n            if line.contains(\"approved\") && !line.contains(\"not approved\") {\n                return Ok(ArchiveReviewVerdict::Approved);\n            }\n            if line.contains(\"reviewed\") || line.contains(\"needs fix\") || line.contains(\"needsfix\")\n            {\n                return Ok(ArchiveReviewVerdict::Reviewed);\n            }\n            if line.contains(\"rejected\") {\n                return Ok(ArchiveReviewVerdict::Rejected);\n            }\n        }\n    }\n\n    // If no verdict found, it's unknown\n    Ok(ArchiveReviewVerdict::Unknown)\n}\n\n/// Get the review file path, preferring review_merge.md over legacy names\n/// @spec apps/agentic-workflow/tech-design/core/interfaces/parser/archive_review.md#source\npub fn get_review_path(change_dir: &Path) -> std::path::PathBuf {\n    let review_merge = change_dir.join(\"review_merge.md\");\n    if review_merge.exists() {\n        return review_merge;\n    }\n    // Fallback to legacy MERGE_REVIEW.md\n    let merge_review = change_dir.join(\"MERGE_REVIEW.md\");\n    if merge_review.exists() {\n        return merge_review;\n    }\n    // Fallback to oldest legacy name\n    change_dir.join(\"ARCHIVE_REVIEW.md\")\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use std::io::Write;\n    use tempfile::NamedTempFile;\n\n    #[test]\n    fn test_parse_approved_checkbox() {\n        let content = r#\"# Merge Review Report\n\n## Verdict\n- [x] APPROVED - Merge quality acceptable\n- [ ] REVIEWED\n- [ ] REJECTED\n\"#;\n\n        let mut file = NamedTempFile::new().unwrap();\n        file.write_all(content.as_bytes()).unwrap();\n        file.flush().unwrap();\n\n        let verdict = parse_archive_review_verdict(file.path()).unwrap();\n        assert_eq!(verdict, ArchiveReviewVerdict::Approved);\n    }\n\n    #[test]\n    fn test_parse_reviewed_checkbox() {\n        let content = r#\"# Merge Review Report\n\n## Verdict\n- [ ] APPROVED\n- [x] REVIEWED - Fix issues above\n- [ ] REJECTED\n\"#;\n\n        let mut file = NamedTempFile::new().unwrap();\n        file.write_all(content.as_bytes()).unwrap();\n        file.flush().unwrap();\n\n        let verdict = parse_archive_review_verdict(file.path()).unwrap();\n        assert_eq!(verdict, ArchiveReviewVerdict::Reviewed);\n    }\n\n    #[test]\n    fn test_parse_rejected_checkbox() {\n        let content = r#\"# Merge Review Report\n\n## Verdict\n- [ ] APPROVED\n- [ ] REVIEWED\n- [x] REJECTED - Fundamental problems\n\"#;\n\n        let mut file = NamedTempFile::new().unwrap();\n        file.write_all(content.as_bytes()).unwrap();\n        file.flush().unwrap();\n\n        let verdict = parse_archive_review_verdict(file.path()).unwrap();\n        assert_eq!(verdict, ArchiveReviewVerdict::Rejected);\n    }\n\n    #[test]\n    fn test_parse_approved_fallback() {\n        // Test fallback format when LLM doesn't use checkbox\n        let content = r#\"# Merge Review\n\n## Summary\nAll good.\n\n**Verdict**: APPROVED\n\"#;\n\n        let mut file = NamedTempFile::new().unwrap();\n        file.write_all(content.as_bytes()).unwrap();\n        file.flush().unwrap();\n\n        let verdict = parse_archive_review_verdict(file.path()).unwrap();\n        assert_eq!(verdict, ArchiveReviewVerdict::Approved);\n    }\n\n    #[test]\n    fn test_parse_reviewed_fallback() {\n        let content = r#\"# Merge Review\n\nVerdict: REVIEWED\n\"#;\n\n        let mut file = NamedTempFile::new().unwrap();\n        file.write_all(content.as_bytes()).unwrap();\n        file.flush().unwrap();\n\n        let verdict = parse_archive_review_verdict(file.path()).unwrap();\n        assert_eq!(verdict, ArchiveReviewVerdict::Reviewed);\n    }\n\n    #[test]\n    fn test_parse_unknown_no_verdict() {\n        let content = r#\"# Merge Review\n\n## Summary\nStill reviewing...\n\"#;\n\n        let mut file = NamedTempFile::new().unwrap();\n        file.write_all(content.as_bytes()).unwrap();\n        file.flush().unwrap();\n\n        let verdict = parse_archive_review_verdict(file.path()).unwrap();\n        assert_eq!(verdict, ArchiveReviewVerdict::Unknown);\n    }\n\n    #[test]\n    fn test_parse_unknown_unchecked_boxes() {\n        let content = r#\"# Merge Review\n\n## Verdict\n- [ ] APPROVED\n- [ ] REVIEWED\n- [ ] REJECTED\n\"#;\n\n        let mut file = NamedTempFile::new().unwrap();\n        file.write_all(content.as_bytes()).unwrap();\n        file.flush().unwrap();\n\n        let verdict = parse_archive_review_verdict(file.path()).unwrap();\n        assert_eq!(verdict, ArchiveReviewVerdict::Unknown);\n    }\n\n    #[test]\n    fn test_file_not_found() {\n        let verdict = parse_archive_review_verdict(Path::new(\"/nonexistent/path\")).unwrap();\n        assert_eq!(verdict, ArchiveReviewVerdict::Unknown);\n    }\n}\n\n// CODEGEN-END\n~~~\n\n## Changes\n<!-- type: changes lang: yaml -->\n\n```yaml\nchanges:\n  - path: apps/agentic-workflow/src/parser/arch